/// <summary>
/// Calculates monetary totals for customer orders and refunds.
/// </summary>
public class OrderProcessor

/// <summary>
/// Calculates the order total by applying the given tax rate to the order amount.
/// </summary>
/// <param name="amt">The pre-tax order amount.</param>
/// <param name="tx">The tax rate expressed as a decimal fraction (for example, 0.07 for 7%).</param>
/// <returns>The order amount including tax.</returns>
public decimal ProcessOrder(decimal amt, decimal tx)

/// <summary>
/// Calculates the refund total by applying the given tax rate to the refunded amount.
/// </summary>
/// <param name="amt">The pre-tax amount being refunded.</param>
/// <param name="tx">The tax rate expressed as a decimal fraction (for example, 0.07 for 7%).</param>
/// <returns>The refund amount including tax.</returns>
public decimal ProcessRefund(decimal amt, decimal tx)
